(function(){"use strict";var raiz=document.documentElement;if(raiz.getAttribute("data-visual")!=="novo")return;if(window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;var SEL='.card, .mod-card, .panel, div[style*="flex: 0 0 250px"]';var alvo=null,ev=null,agendado=false;function pintar(){agendado=false;if(!alvo||!ev)return;var r=alvo.getBoundingClientRect();alvo.style.setProperty("--mx",Math.round(ev.clientX-r.left)+"px");alvo.style.setProperty("--my",Math.round(ev.clientY-r.top)+"px")}document.addEventListener("pointermove",(function(e){var el=e.target&&e.target.closest?e.target.closest(SEL):null;if(alvo&&alvo!==el){alvo.style.removeProperty("--mx");alvo.style.removeProperty("--my")}alvo=el;ev=e;if(el&&!agendado){agendado=true;requestAnimationFrame(pintar)}}),{passive:true});function colunas(){var cols=document.querySelectorAll('div[style*="flex: 0 0 250px"]');for(var i=0;i<cols.length;i++){var c=cols[i],dot=c.firstElementChild&&c.firstElementChild.firstElementChild;var cor=dot&&dot.style&&dot.style.background;if(cor&&c.style.getPropertyValue("--k")!==cor)c.style.setProperty("--k",cor)}}var t=0;function agendarColunas(){clearTimeout(t);t=setTimeout(colunas,120)}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",agendarColunas);else agendarColunas();new MutationObserver(agendarColunas).observe(document.body||raiz,{childList:true,subtree:true})})();